    Set<V> partition1 = new HashSet<>();
    Set<V> partition2 = new HashSet<>();

    // Determine the number of vertices in the graph (numVertices)
    int numVertices = target.numVertices();

    // Add all vertices from the original graph to the first partition
    for (V vertex : target.getVertices()) {
        partition1.add(vertex);
    }

    // Iterate through the desired number of edges to add
    for (int i = 0; i < target.numVertices() * (numVertices - 1) / 2; i++) {
        // Randomly select a vertex from the first partition and another from the second
        V vertex1 = partition1.stream().skip((int) (Math.random() * partition1.size())).findFirst().get();
        V vertex2 = partition2.stream().skip((int) (Math.random() * partition2.size())).findFirst().get();

        // Add an edge between the two chosen vertices
        target.addEdge(vertex1, vertex2);
        result.add((" edge " + vertex1 + " " + vertex2));
    }

    // Store the partition labels in the result map
    resultMap.put("partition1", partition1);
    resultMap.put("partition2", partition2);
