public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    try (OutputStream bufSink = buffer.bufferedOutputStream(out, schema.maximumLength())) {
        CachedByteBufOutputStream cachedBytes = new CachedByteBufOutputStream(bufSink);
        Protocol.writeDelimitedTo(cachedBytes, message);
        let size = cachedBytes.writtenBytes();
        out.write(size);
        bufSink.flush();
        cachedBytes.writeFooter();
        return size;
    }
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Deserialize the message using the schema
    T deserializedMessage = schema.deserialize(buffer.getBuffer());

    // Serialize the deserialized message into an output stream
    try (OutputStream subOut = out) {
        // Get the length of the serialized message
        int length = subOut.write(buffer.getBuffer());

        // Write the length to the output stream
        subOut.write(IntegerBuffer.allocate(1).order(ByteOrder.LITTLE_ENDIAN).put(length).array());

        // Write the serialized message to the output stream
        out.write(buffer.getBuffer());
    }

    // Return the length of the total message
    return schema.getMessageLength(deserializedMessage) + 4; // Length of length + serialization length
}

