public Mappings diffStructure(String tableName, Mappings mappings) {
    // Ensure that the input mappings, history mapping, and current mapping are all in the same format and are not empty
    if ( mappings == null || mappings.isEmpty() || mappings.getHistory() == null || mappings.getCurrent() == null ) {
        throw new IllegalArgumentException("Input mappings are invalid.");
    }

    Mappings diffStructMap = new Mappings();

    // Retrieve all fields from the input mappings
    Set<String> allFields = mappings.getCurrent().entrySet().stream()
                                        .map(Map.Entry::getKey)
                                        .collect(Collectors.toSet());

    // Create a mapping from the input mappings to the current mappings
    List<Map.Entry<String, Object>> diffSource = new ArrayList<>();
    for (Map.Entry<String, Object> entry : mappings.getCurrent().entrySet()) {
        diffSource.add(Map.entry(entry.getKey(), entry.getValue()));
    }

    // Compare the input mappings with the current mappings and build the difference structure
    for (Map.Entry<String, Object> entry : mappings.getHistory().entrySet()) {
        if (!allFields.contains(entry.getKey())) {
            diffStructMap.getSources().add(Map.entry(entry.getKey(), entry.getValue()));
        } else if (!entry.getValue().equals(mappings.getCurrent().get(entry.getKey()))) {
            diffStructMap.getNewFields().add(Map.entry(entry.getKey(), entry.getValue()));
        }
    }

    // Set the status of source mappings
    for (Map.Entry<String, Object> entry : diffSource) {
        if (entry.getValue() instanceof Map) {
            entry.setValue(diffSource.get(mappings.getHistory().get(entry.getKey())).getValue());
        }
    }

    return diffStructMap;
}

