public static int computeUTF8Size(CharSequence str, int index, int len) {
    int charIndex = index;
    int result = 0;

    while (charIndex < index + len) {
        int utf8Length = 1;
        char c = str.charAt(charIndex);

        // Check if the character is a continuation byte
        if ((c & 0x80) == 0x80) {
            utf8Length = 2;
            if ((c & 0xC0) == 0xC0) {
                utf8Length = 3;
                if ((c & 0xE0) == 0xE0) {
                    utf8Length = 4;
                }
            }
        }

        charIndex += utf8Length;
        result += utf8Length;
    }

    return result;
}

public static int computeUTF8Size(CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else if (c <= 0x10FFFF) {
            size += 4;
        } else {
