        int utf8Size = 0;
        // Get the length of the non-zero part of the UTF-8 string
        for (int i = index; i < index + len; i++) {
            char c = str.charAt(i);
            if ((c & 0xF0) == 0xE0) utf8Size += 3; // 3 bytes if byte1 <0x80, byte2 by 0xc0-0 BF, byte3 < 0x80
            else if ((c & 0xE0) == 0xF8) utf8Size += 4; // 4 bytes if byte1 <0x80, byte2 by 0xc0-0xBF, byte3 and byte4 by 0x80-0x3F
            else if ((c & 0xF0) == 0xF0) utf8Size += 5; // 5 bytes for byte1 <0x80, byte2 by 0xc0-0xBF, byte3 and byte4 and byte5 by 0x80-0x1F
            else if (c >= 0x80 && c <= 0xBF) utf8Size += 1; // 1 byte otherwise
        }
        // Return the total size minus the length indicating the non-zero part
        return utf8Size - len;
    }

