    int size = 0;
    while (index + size < len) {
        int prevByte = str.charAt(index + size);
        size += 1;
        if (prevByte >= 0xe0) { // Three-byte sequence
            size += prevByte >= 0xf0 ? 2 : 1;
        } else if (prevByte >= 0xc0) { // Two-byte sequence
            size += 1;
        }
    }

    return size;
}

