public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int size = 0;
    Node<Object[]> currentNode = node;
    while (currentNode != null) {
        out.writeInt(currentNode.getEntries().length);
        for (int i = 0; i < currentNode.getEntries().length; i++) {
            out.writeObject(currentNode.getEntries()[i]);
        }
        size += currentNode.getEntries().length * Integer.BYTES + currentNode.getEntries()[0].length + Integer.BYTES;
        currentNode = currentNode.getNextNode();
    }
    return size;
}

