public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    RemoteOutputStream remoteOutputStream = (RemoteOutputStream) out;
    RemoteOutputStream.Node current = node;
    long totalWritten = 0;

    while (current != null) {
        if (current.isDirty()) {
            byte[] buffer = Node.bytes(current.getData());
            int size = remoteOutputStream.write(buffer);
            totalWritten += size;
            remoteOutputStream.protocol().network().watch().record(out, remoteOutputStream.getPath(), current.getHost(), RemoteOutputStream.Node.KEY, size);

            current.setData(ByteBuffer.wrap(buffer).clear());
            current.markDirty(false);
        }
        current = current.getNext();
    }

    return (int) totalWritten;
}

