    if (desiredCapacity < 2) {
        return 2;
    }

    int maxPrime = desiredCapacity - 1;
    for (int i = 5; i * i <= maxPrime; i += 6) {
        if (isPrime(i)) {
            maxPrime = i;
        }
        if (isPrime(i + 2)) {
            maxPrime = i + 2;
        }
    }

    // Check if the maximum prime meets the requirement
    return maxPrime * (11 * (Math.pow(0.3, Math.log(maxPrime)))) >= desiredCapacity ? maxPrime : maxPrime + 2;
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 1) throw new IllegalArgumentException("Desired capacity must be at least 1.");

    if (desiredCapacity >= 1000) {
        // Start from the 11th prime number and get the next one
        int primeCandidate = 11;
        while (true) {
            if (isPrime(primeCandidate)) break;
            primeCandidate++;
        }
        return primeCandidate;
    } else {
        // Start from the next prime number after the square root of desiredCapacity
        int sqrtDesiredCapacity = (int) Math.sqrt(desiredCapacity);
        int primeCandidate = nextPrime(sqrtDesiredCapacity) + 1;
        while (true) {
            if (isPrime(primeCandidate)) break;
            primeCandidate++;
        }
        return primeCandidate;
    }
