public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int length = str.length();
    for (int i = 0; i < length; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < length) {
            char next = str.charAt(i + 1);
            if (next == 't') {
                sb.append('\t');
                i++; // Skip the next character after tab
            } else if (next == 'n') {
                sb.append('\n');
                i++; // Skip the next character after newline
            } else {
                sb.append('\\');
                sb.append(next);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    StringBuilder newStr = new StringBuilder(str.length());
    int prevEsc = -1;

    for (int i = 0; i < str.length(); i++) {
        if (str.charAt(i) == '\\') {
            if (prevEsc >= 0) { // Check if there's an escaped character
              char newChar = str.charAt(i + 1);
              switch (newChar) {
                case 'n':
                  newStr.append('\n');
                  break;
                case 't':
                  newStr.append('\t');
                  break;
                case 'b':
                  newStr.append('\b');
                  break;
                case 'f':
                  newStr.append('\f');
                  break;
                default:
                  // Handle unescaped characters as needed
                  newStr.append(newChar);
                  break;
              }
              i += 1; // Skip the next character (escaped character itself)
            } else {
              prevEsc = i;
            }
        } else {
            newStr.append(str.charAt(i));
        }
    }

    return newStr.toString();
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) return null;
    int len = str.length();
    StringBuilder result = new StringBuilder(len);
    boolean escaped = false;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (!escaped) {
            if (c != '\\') {
                result.append(c);
            } else {
                escaped = true;
            }
        } else {
            if (c == '\n') {
                result.append("\n");
            } else if (c == 'r') {
                result.append("\r");
            } else {
                result.append('\\');
                result.append(c);
                escaped = false;
            }
        }
    }
    return result.toString();
}

