    GraphPath<V,E> path = new GraphPath<>();

    for (E edge : tour) {
        V source = edge.getSource();
        V target = edge.getTarget();
        if (!visited.contains(new GraphNode<>(source, edge))) {
            visited.add(new GraphNode<>(source, edge));
            addPathFromSource(source, edge.getWeight(), path, graph, visited);
        }
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    GraphPath<V,E> graphPath = new GraphPath<>();
