void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel) {
    // Old bucket
    Set<Integer> oldBucket = bucketsByLabel.get(minLabel);
    // Make old bucket empty
    oldBucket.clear();
    // Deallocate memory associated with current bucket
    bucketsByLabel.set(minLabel, null);
    // Update labels
    for (int label : labels) {
        if (label != minLabel) {
            bucketsByLabel.set(label, oldBucket);
        }
    }
}

void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
  List<Integer> nonEmptyBucket = bucketsByLabel.get(minLabel - 1);
  if(nonEmptyBucket.size() > 0) {
    int maxLabel = labels.get(nonEmptyBucket.size() - 1) + 1;
    for(int i = 1; i <= maxLabel; i++) {
      bucketsByLabel.get(i).addAll(nonEmptyBucket);
    }
    bucketsByLabel.get(minLabel - 1).clear();
    labels.clear();
    nonEmptyBucket = new ArrayList<>();
  }
  if(minLabel > 1) reload(bucketsByLabel, labels, minLabel - 1);
}

private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (i == minLabel) {
            bucketsByLabel.get(i).clear();
            labels.set(i, 0);
        } else {
            labels.set(i, 1);
        }
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (bucketsByLabel.get(0).isEmpty()) {
            bucketsByLabel.set(0, bucketsByLabel.get(i));
        }
        bucketsByLabel.remove(i);
    }
    labels.removeAll(bucketsByLabel.get(0));
    labels.addFirst(0);
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        if (bucketsByLabel.get(i).contains(minLabel)) {
            for (int label : labels) {
                if (label != minLabel) {
                    bucketsByLabel.get(label).remove(minLabel);
                }
            }
            bucketsByLabel.get(0).addAll(bucketsByLabel.get(minLabel));
            bucketsByLabel.remove(minLabel);
        }
    }
}

