public boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    boolean[] visited = new boolean[graph.numVertices()];
    for (V vertex : vertices) {
        if (visited[vertex.toInt()] || !graph.containsVertex(vertex)) {
            return false;
        }
        visited[vertex.toInt()] = true;
        for (E edge : graph.incidentEdgesOf(vertex)) {
            if (!visited[edge.to().toInt()]) {
                return false;
            }
        }
    }
    return true;
}

