public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }

    if (substring.length() > str.length() - index) {
        return false;
    }

    for (int i = index, j = 0; i < str.length() && j < substring.length(); i++, j++) {
        if (str.charAt(i) != substring.charAt(j)) {
            return false;
        }
    }

    return true;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        throw new IllegalArgumentException("Strings must not be null");
    }
    if (index > str.length() || index < 0) {
        throw new IllegalArgumentException("Index must be within the bounds of the string");
    }
    if (substring.length() > str.length() - index) {
        return false;
    }
    return str.regionMatches(true, index, substring, 0, substring.length());
}

